import{_ as i,C as s,o as n,c as t,a5 as c,E as l,j as a,a as o}from"./chunks/framework.BwlBv862.js";const g=JSON.parse('{"title":"Preparar colaboración y acceso de equipos","description":"","frontmatter":{"title":"Preparar colaboración y acceso de equipos","docId":"user.cloud.collaboration","translationKey":"user.cloud.collaboration","locale":"es","audience":"user","featureStatus":"experimental","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"4a97f64b6bdc818ebb8d16eec1e67d95a2d0eae0b75f7cfd5c1493bf27244684","translationRevision":"63e8fedabc20cf5faa895b93cc0437db2a72a46f290977cd6c297d4eba82b3d6","order":30},"headers":[],"relativePath":"es/user/cloud/collaboration.md","filePath":"es/user/cloud/collaboration.md","lastUpdated":1794611623000}'),d={name:"es/user/cloud/collaboration.md"};function p(u,e,m,b,f,v){const r=s("DemoFrame");return n(),t("div",null,[e[0]||(e[0]=c('<h1 id="prepare-collaboration-and-team-access" tabindex="-1">Preparar colaboración y acceso de equipos <a class="header-anchor" href="#prepare-collaboration-and-team-access" aria-label="Permalink to &quot;Preparar colaboración y acceso de equipos {#prepare-collaboration-and-team-access}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo y requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objetivo y requisitos {#goal-and-prerequisites}&quot;">​</a></h2><p>Asigna a otro operador un papel definido manteniendo el control del propietario. Necesitas un host de escritorio compatible y elegir entre colaboración local/nativa y Teams vinculado a cuentas. Teams también requiere <a href="./account.html">sesión de Cloud</a> y soporte del servicio desplegado. Comienza con acceso de lectura en un entorno de prueba.</p><h2 id="configure-owner-access" tabindex="-1">Configurar acceso del propietario <a class="header-anchor" href="#configure-owner-access" aria-label="Permalink to &quot;Configurar acceso del propietario {#configure-owner-access}&quot;">​</a></h2><ol><li>Abre <strong>Settings → Collaboration</strong>. Inspecciona el estado y activa/configura el receptor o la pasarela previstos mediante sus controles.</li><li>Revisa los orígenes permitidos y la matriz de acceso antes de crear una invitación. Elige únicamente las áreas, operaciones y recursos necesarios.</li><li>Crea la invitación y entrega su enlace/token privado por un canal confiable. Una invitación no equivale a una sesión activa aprobada.</li><li>Inspecciona las solicitudes pendientes y sus permisos. Aprueba solo al operador esperado y confirma su identidad visible y conexión.</li><li>Usa el inspector de acceso para revisar modificaciones posteriores. Revoca invitaciones, identidades o sesiones cuando dejen de necesitar acceso.</li></ol><p>Editar una definición delegada, adoptarla como propietario y aprobar su ejecución son decisiones distintas. Lee el código guardado, las acciones referenciadas y los permisos en la revisión específica. Una vista previa por sí sola no autoriza efectos.</p><h2 id="prepare-an-account-based-team" tabindex="-1">Preparar un equipo vinculado a cuentas <a class="header-anchor" href="#prepare-an-account-based-team" aria-label="Permalink to &quot;Preparar un equipo vinculado a cuentas {#prepare-an-account-based-team}&quot;">​</a></h2><p>Cuando aparezca <strong>Settings → Teams</strong>, crea un equipo con nombre y selecciónalo. Registra <strong>este PC</strong> como host con una etiqueta reconocible, pulsa <strong>Start serving</strong> e inspecciona el enlace. La creación y el registro del host local están conectados en el frontend; son pasos distintos de invitar a otra persona. Los dispositivos controladores tienen su propio papel de registro.</p><p>Elige destinatario, papel y duración de invitación; revisa solicitudes, miembros y dispositivos. La búsqueda por apodo requiere un endpoint de backend desplegado por separado y puede no estar disponible en el servicio actual. Un fallo de búsqueda no demuestra que la persona carezca de cuenta; tampoco sustituyas la selección por un ID arbitrario.</p><h2 id="expected-result-and-status" tabindex="-1">Resultado esperado y estado <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Resultado esperado y estado {#expected-result-and-status}&quot;">​</a></h2><p>Existen controles del propietario y flujos frontend de creación/registro de equipos. La colaboración remota completa es experimental: aquí no se acredita operación LIVE entre dos PC reales, búsqueda en producción, comportamiento NAT/retransmisión ni recuperación de todos los efectos y plataformas. Un enlace preparado no demuestra por sí solo el funcionamiento íntegro de los permisos para tu acción.</p><h2 id="recovery" tabindex="-1">Recuperación <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Recuperación {#recovery}&quot;">​</a></h2><p>Si cambian permisos o revisiones del host, carga y revisa otra vez. Ante órdenes sin confirmar, inspecciona el resultado registrado antes de repetir. Detén el servicio o revoca acceso al terminar. Mantén tokens de invitación y credenciales fuera de los <a href="./../preferences/troubleshooting.html">informes públicos</a>.</p>',13)),l(r,{scenario:"collaboration",locale:"es",title:"Demo de collaboration"}),e[1]||(e[1]=a("h2",{id:"operational-details",tabindex:"-1"},[o("Detalles de operación "),a("a",{class:"header-anchor",href:"#operational-details","aria-label":'Permalink to "Detalles de operación {#operational-details}"'},"​")],-1)),e[2]||(e[2]=a("p",null,[o("Tras unirse/aprobar acceso Teams, el host debe confirmar la revisión vigente del permiso nativo. "),a("code",null,"pendingHost"),o(" indica espera; transporte activo o pertenencia no conceden acceso por sí solos. Recarga tras cambiar permisos y revisa host/dispositivo. Observer orienta a lectura; moderator añade controles concretos, automationEditor edición concreta y custom requiere política explícita revisada. Ninguno concede scripts/efectos ilimitados. Consulta "),a("a",{href:"./../../developer/collaboration.html#operational-details"},"roles y confirmación"),o(" si los controles no explican un rechazo.")],-1))])}const y=i(d,[["render",p]]);export{g as __pageData,y as default};
